// ============================================================================
// FreeLang OAuth - GitHub Strategy
// ============================================================================
// 기능: GitHub OAuth 2.0 (소셜 로그인)
// 클라이언트 ID/Secret: config/oauth.env에서 로드

use std::io::*
use "./auth"

pub struct GitHubOAuthConfig {
  client_id: string,
  client_secret: string,
  redirect_uri: string,
  scope: string
}

pub struct GitHubTokenResponse {
  access_token: string,
  token_type: string,
  scope: string,
  expires_in: i32
}

pub struct GitHubUserInfo {
  id: i64,
  login: string,
  name: string,
  email: string,
  avatar_url: string,
  bio: string,
  company: string,
  location: string
}

// ============================================================================
// OAuth 흐름
// ============================================================================

pub fn github_get_auth_url(config: GitHubOAuthConfig) -> string
  intent "GitHub OAuth 인증 URL 생성"
  do
    let scope = string_replace_all(config.scope, " ", "%20")
    let auth_url = "https://github.com/login/oauth/authorize"
      + "?client_id=" + config.client_id
      + "&redirect_uri=" + config.redirect_uri
      + "&scope=" + scope
      + "&state=" + generate_random_state()
      + "&allow_signup=true"

    return auth_url
  end

pub fn github_exchange_code_for_token(config: GitHubOAuthConfig, code: string) -> Result<GitHubTokenResponse, string>
  intent "GitHub OAuth 인증 코드 → 토큰 교환"
  do
    // HTTP POST 요청: https://github.com/login/oauth/access_token
    // 헤더: Accept: application/json
    // 파라미터: code, client_id, client_secret, redirect_uri

    // 응답 파싱 (JSON)
    // access_token, token_type, scope, expires_in

    // 임시 구현
    return Ok(GitHubTokenResponse {
      access_token: "github_access_token_xxx",
      token_type: "bearer",
      scope: "user:email read:user",
      expires_in: 3600
    })
  end

pub fn github_get_user_info(access_token: string) -> Result<GitHubUserInfo, string>
  intent "GitHub API에서 사용자 정보 조회"
  do
    // HTTP GET 요청: https://api.github.com/user
    // 헤더: Authorization: Bearer {access_token}
    //       Accept: application/vnd.github.v3+json

    // 응답 파싱 (JSON)
    // id, login, name, email, avatar_url, bio, company, location

    // 임시 구현
    return Ok(GitHubUserInfo {
      id: 123456789,
      login: "johndoe",
      name: "John Doe",
      email: "john@example.com",
      avatar_url: "https://avatars.githubusercontent.com/u/123456789",
      bio: "Developer",
      company: "Example Corp",
      location: "Seoul, Korea"
    })
  end

// ============================================================================
// 헬퍼 함수
// ============================================================================

fn generate_random_state() -> string
  intent "OAuth state 토큰 생성 (CSRF 방지)"
  do
    // TODO: 크립토그래픽 난수 생성
    return "random_state_token_xyz"
  end

fn string_replace_all(s: string, from: string, to: string) -> string
  intent "문자열 전체 치환"
  do
    // TODO: 구현
    return s
  end

