// ============================================================================
// FreeLang Blog Server - 완전 독립 구현
// ============================================================================
// 의존성: 0개 (FreeLang 표준 라이브러리만 사용)
// 포트: 5021
// 기능: REST API, 정적 파일 서빙, 플러그인 시스템

use std::io::*
use std::fs::*
use std::net::*

// HTTP 엔진 import ✅
use "../engine/http_parser"
use "../engine/http_handler"

// Blog 모듈 import ✅
use "./blog-db"
use "./blog-api"
use "./file-io"  // 파일 I/O 모듈

// Phase 4: 모니터링 import ✅
use "./error-logger"

// OAuth 2.0 import ✅
use "./oauth-google"
use "./oauth-github"
use "./oauth-naver"
use "./auth"

// ============================================================================
// PART 1: HTTP 요청 핸들러 (HTTP Engine과 Blog API 통합)
// ============================================================================

fn handle_http_request(req: HttpRequest) -> HttpResponse {
  intent "HTTP 요청 처리 및 응답 생성 (모니터링 포함)"
  do
    print("📨 Processing: " + req.method + " " + req.path)

    // ✅ 요청 모니터링 기록
    let request_start_time = get_request_start_time()
    error_logger::log_info("HTTP 요청: " + req.method + " " + req.path)

    // 요청 타입에 따라 라우팅
    let response = route_request(req, &mut GLOBAL_DB)

    // ✅ 응답 모니터링 기록
    let request_end_time = get_request_end_time()
    let request_duration_ms = request_end_time - request_start_time
    error_logger::log_info("응답: " + req.method + " " + req.path + " → " + string_of_int(response.status) + " (" + string_of_int(request_duration_ms) + "ms)")

    // ✅ 에러 로그 (5xx 응답)
    if response.status >= 500
      error_logger::log_error("서버 에러 발생: " + req.method + " " + req.path + " (상태: " + string_of_int(response.status) + ")")
    end

    // ✅ 경고 로그 (4xx 응답)
    if response.status >= 400 && response.status < 500
      error_logger::log_warn("클라이언트 에러: " + req.method + " " + req.path + " (상태: " + string_of_int(response.status) + ")")
    end

    return response
  end
}

// ============================================================================
// PART 2: 플러그인 시스템 통합
// ============================================================================

pub struct PluginManager {
  plugins: map<string, Plugin>,
  hooks: map<string, array<fn>>
}

pub struct Plugin {
  name: string,
  version: string,
  enabled: bool,
  uiComponents: map<string, fn() -> string>
}

// 기본 플러그인 등록
fn initialize_plugins(manager: &mut PluginManager) -> void {
  intent "5개 기본 플러그인 초기화"
  do
    // 1. Comments Plugin
    let comments = Plugin {
      name: "comments",
      version: "1.0.0",
      enabled: true,
      uiComponents: {}
    }
    manager.plugins["comments"] = comments

    // 2. Analytics Plugin
    let analytics = Plugin {
      name: "analytics",
      version: "1.0.0",
      enabled: true,
      uiComponents: {}
    }
    manager.plugins["analytics"] = analytics

    // 3. Newsletter Plugin
    let newsletter = Plugin {
      name: "newsletter",
      version: "1.0.0",
      enabled: true,
      uiComponents: {}
    }
    manager.plugins["newsletter"] = newsletter

    // 4. Gallery Plugin
    let gallery = Plugin {
      name: "gallery",
      version: "1.0.0",
      enabled: true,
      uiComponents: {}
    }
    manager.plugins["gallery"] = gallery

    // 5. Related Posts Plugin
    let related_posts = Plugin {
      name: "related-posts",
      version: "1.0.0",
      enabled: true,
      uiComponents: {}
    }
    manager.plugins["related-posts"] = related_posts

    print("✅ 5개 플러그인 초기화됨")
  end
}

// ============================================================================
// PART 3: 글로벌 상태 (DB, 플러그인)
// ============================================================================

let GLOBAL_DB = blog_db_new("/tmp/blog-data.json")
let GLOBAL_PLUGINS = PluginManager { plugins: {}, hooks: {} }

// ============================================================================
// PART 4: 메인 서버 함수
// ============================================================================

pub fn main() -> void {
  intent "FreeLang Blog Server 메인"
  do
    print("🚀 FreeLang Blog Server Starting...")
    print("────────────────────────────────────")

    // 1. 플러그인 초기화
    initialize_plugins(&mut GLOBAL_PLUGINS)

    // 2. 데이터베이스 로드
    print("📂 Loading database...")
    // blog_db_load(&GLOBAL_DB)

    // 3. HTTP 서버 시작
    print("🌐 Starting HTTP server on port 5021...")
    print("   → http://localhost:5021")
    print("")

    // HTTP 엔진 시작 ✅ (HTTP Engine 통합)
    // 0.0.0.0에 바인딩: nginx reverse proxy를 통한 외부 접근 허용
    match http_server_main("0.0.0.0", 5021, handle_http_request)
      Ok(()) => {
        print("✨ Server ready!")
      }
      Err(e) => {
        print("❌ Server error: " + e)
        return void
      }
    end
    print("")
    print("📌 API 엔드포인트:")
    print("   GET    /api/blogs        - 포스트 목록")
    print("   POST   /api/blogs        - 포스트 생성")
    print("   GET    /api/blogs/:id    - 포스트 상세")
    print("   PUT    /api/blogs/:id    - 포스트 수정")
    print("   DELETE /api/blogs/:id    - 포스트 삭제")
    print("   POST   /api/blogs/:id/view   - 조회수 증가")
    print("   POST   /api/blogs/:id/like   - 좋아요 추가")
    print("")
    print("🔌 플러그인 API:")
    print("   GET /api/plugins           - 플러그인 목록")
    print("   GET /api/plugins/ui/:pos   - 플러그인 UI")
    print("")

    // TODO: HTTP 서버 실제 실행
    return void
  end
}

// ============================================================================
// PART 5: 헬퍼 함수들
// ============================================================================

fn print(msg: string) -> void {
  intent "메시지 출력"
  do
    // 표준 출력 - FreeLang std::io 사용
    println(msg)
    return void
  end
}

fn blog_db_new(path: string) -> BlogDb {
  intent "블로그 데이터베이스 생성"
  do
    return BlogDb {
      posts: {},
      nextId: 1,
      dataPath: path
    }
  end
}

// ============================================================================
// PART 6: 요청 라우팅 (API 통합)
// ============================================================================

fn route_request(req: HttpRequest, db: &mut BlogDb) -> HttpResponse {
  intent "HTTP 요청 라우팅 (Phase 3 확장 + 모니터링 + OAuth)"
  do
    // ✅ 요청 라우팅 모니터링
    error_logger::log_debug("라우팅 시작: " + req.method + " " + req.path)

    // IP 기반 레이트 제한 확인 ⚡
    let ip = "127.0.0.1"  // TODO: req.ip 추출
    match security::check_rate_limit(ip)
      Ok(true) => {}
      Err(e) => {
        println("⛔ " + e)
        error_logger::log_warn("레이트 제한 초과: " + ip)
        return create_error_response(429, e)
      }
    end

    // CORS 검증 (if needed)
    let origin = "http://localhost:3000"  // TODO: req headers에서 추출
    let cors_headers = security::get_cors_headers(origin)

    // 정적 파일 서빙
    if req.method == "GET" && req.path == "/"
      return serve_index_html()
    end

    // API 문서 (Swagger UI)
    if req.method == "GET" && req.path == "/api/docs"
      return serve_swagger_ui()
    end

    if req.method == "GET" && req.path == "/api/docs/spec"
      return serve_api_spec()
    end

    // OAuth 라우팅
    if starts_with(req.path, "/auth/")
      return route_oauth_api(req)
    end

    // Blog API
    if starts_with(req.path, "/api/blogs")
      return route_blog_api(req, db)
    end

    // Plugin API
    if starts_with(req.path, "/api/plugins")
      return route_plugin_api(req)
    end

    // 404
    return create_error_response(404, "Not Found")
  end
}

fn route_blog_api(req: HttpRequest, db: &mut BlogDb) -> HttpResponse {
  intent "Blog API 라우팅"
  do
    // GET /api/blogs
    if req.method == "GET" && req.path == "/api/blogs"
      return handle_list_posts(req, db)
    end

    // POST /api/blogs
    if req.method == "POST" && req.path == "/api/blogs"
      return handle_create_post(req, db)
    end

    // 기타 blog API 처리...
    return create_error_response(404, "Blog API not found")
  end
}

fn route_plugin_api(req: HttpRequest) -> HttpResponse {
  intent "Plugin API 라우팅"
  do
    // GET /api/plugins
    if req.method == "GET" && req.path == "/api/plugins"
      return handle_list_plugins(req)
    end

    // GET /api/plugins/ui/:position
    if starts_with(req.path, "/api/plugins/ui/")
      let position = extract_position(req.path)
      return handle_plugin_ui(position)
    end

    return create_error_response(404, "Plugin API not found")
  end
}

fn route_oauth_api(req: HttpRequest) -> HttpResponse {
  intent "OAuth 2.0 라우팅 (Google, GitHub, Naver)"
  do
    // Google OAuth
    if req.method == "GET" && req.path == "/auth/google/login"
      return handle_google_login(req)
    end

    if req.method == "GET" && starts_with(req.path, "/auth/google/callback")
      return handle_google_callback(req)
    end

    // GitHub OAuth
    if req.method == "GET" && req.path == "/auth/github/login"
      return handle_github_login(req)
    end

    if req.method == "GET" && starts_with(req.path, "/auth/github/callback")
      return handle_github_callback(req)
    end

    // Naver OAuth
    if req.method == "GET" && req.path == "/auth/naver/login"
      return handle_naver_login(req)
    end

    if req.method == "GET" && starts_with(req.path, "/auth/naver/callback")
      return handle_naver_callback(req)
    end

    return create_error_response(404, "OAuth API not found")
  end
}

